let motionOn=read('academy-motion-v1',true);function reducedMotion(){return !motionOn||(typeof matchMedia==='function'&&matchMedia('(prefers-reduced-motion: reduce)').matches)}
function toggleMotion(){motionOn=!motionOn;persist('academy-motion-v1',motionOn);document.body.classList.toggle('still',!motionOn);toast(motionOn?'动画已开启':'动画已关闭，实验功能不变')}
const originalStop=stopAnimation;stopAnimation=function(){originalStop();clearInterval(observeTimer);observeTimer=null;guideBusy=false};
const WORLDS=[['水果邮局','帮小芽把每一颗水果送对地方。','#e3edcc'],['星光发射场','把预测调准，让每次尝试更接近目标。','#f4e1c7'],['大脑花园','点亮连接，让小芽学会复杂的规律。','#e2dfef'],['像素画室','从一格像素开始，教小芽看世界。','#d5e8ec'],['迷宫小镇','找得到路，也要知道为什么这样走。','#e2ebd2'],['创想港湾','带上新能力，做出你自己的 AI。','#f2e0ce']];
function botArt(mood='happy'){return `<g class="bot-body"><ellipse cx="65" cy="137" rx="38" ry="6" fill="#2f573d18"/><g class="bot-bob"><path d="M65 21V10" stroke="#385745" stroke-width="3"/><circle class="antenna-light" cx="65" cy="8" r="5" fill="#edb657"/><rect x="23" y="24" width="84" height="66" rx="22" fill="#fffef3" stroke="#385745" stroke-width="2.5"/><rect x="31" y="36" width="68" height="40" rx="14" fill="#2d4d42"/><g class="bot-eyes">${mood==='happy'?'<path d="M44 56q5-9 10 0m22 0q5-9 10 0" fill="none" stroke="#d8efa5" stroke-width="4" stroke-linecap="round"/>':'<rect x="44" y="47" width="7" height="13" rx="3" fill="#d8efa5"/><rect x="79" y="47" width="7" height="13" rx="3" fill="#d8efa5"/>'}</g><path d="M60 66q5 ${mood==='confused'?'-5':'5'} 10 0" fill="none" stroke="#d8efa5" stroke-width="2"/><rect x="35" y="93" width="60" height="36" rx="13" fill="#c4df93" stroke="#385745" stroke-width="2.5"/><circle cx="65" cy="109" r="7" fill="#fbf5cc"/><path d="M35 100q-17 0-18 16" fill="none" stroke="#799368" stroke-width="8" stroke-linecap="round"/><g class="bot-hand"><path d="M95 101q18-2 20-20" fill="none" stroke="#799368" stroke-width="8" stroke-linecap="round"/></g><path d="M47 129v7m36-7v7" stroke="#799368" stroke-width="10" stroke-linecap="round"/></g></g>`}
function fruitArt(kind,x,y,size=1){return `<g transform="translate(${x} ${y}) scale(${size})">${kind===0?'<path d="M0-12q-14-9-20 5t8 27q8 3 12-1 8 5 15-1Q30-6 13-14q-7-3-13 2" fill="#87b675" stroke="#416640" stroke-width="2"/><path d="M1-10q-3-10 1-15" fill="none" stroke="#6b573c" stroke-width="3"/><path d="M3-21q14-9 18 0-12 5-18 0" fill="#557e4b"/>':'<circle r="20" fill="#efac67" stroke="#b77b49" stroke-width="2"/><path d="M0-19q5-13 18-10-2 12-18 10" fill="#7b9d60"/><circle cx="-7" cy="-5" r="3" fill="#ffd79a"/>'}<circle cx="-6" cy="4" r="1.6" fill="#385745"/><circle cx="7" cy="4" r="1.6" fill="#385745"/><path d="M-2 10q3 3 6 0" stroke="#385745" fill="none" stroke-width="1.5"/></g>`}
function sceneArt(ch,mood='happy',compact=false){let accent=WORLDS[ch][2],decor='';
 if(ch===0)decor=`<path d="M15 149Q45 83 115 134T350 142" fill="#b9d794"/><g class="fruit-drift">${fruitArt(0,75,103,.8)}${fruitArt(1,266,84,.9)}</g><path d="M221 140h67l-8 36h-51z" fill="#f5d8a4" stroke="#aa8156" stroke-width="2"/><path d="M232 144v29m16-29v29m17-29v29" stroke="#caa06d"/><path class="flight-line" d="M97 92Q175 18 249 97" fill="none" stroke="#7e9d69" stroke-width="2" stroke-dasharray="4 6"/>`;
 if(ch===1)decor=`<circle cx="269" cy="93" r="45" fill="#fdf8e8" stroke="#d68c63" stroke-width="3"/><circle cx="269" cy="93" r="30" fill="none" stroke="#e5ba89" stroke-width="8"/><circle cx="269" cy="93" r="12" fill="#dd9468"/><path class="flight-line" d="M46 147Q135 28 261 91" fill="none" stroke="#85936c" stroke-width="3" stroke-dasharray="5 6"/><g class="star-orbit"><path d="M65 61l6 12 13 2-10 9 2 13-11-6-11 6 2-13-10-9 13-2z" fill="#efc96e"/></g>`;
 if(ch===2)decor=`<g stroke="#918bb7" stroke-width="3">${[[50,85,116,52],[50,85,112,126],[112,126,255,129],[116,52,260,60],[255,129,296,95],[260,60,296,95]].map(a=>`<path class="signal" d="M${a[0]} ${a[1]}L${a[2]} ${a[3]}"/>`).join('')}</g>${[[50,85],[116,52],[112,126],[255,129],[260,60],[296,95]].map((p,i)=>`<circle class="node-glow" style="animation-delay:${i*.25}s" cx="${p[0]}" cy="${p[1]}" r="12" fill="${i%2?'#c2b9e0':'#f9efd2'}" stroke="#8f83ab" stroke-width="2"/>`).join('')}`;
 if(ch===3)decor=`<rect x="220" y="38" width="89" height="107" rx="10" fill="#fffaf0" stroke="#73949a" stroke-width="3"/>${Array.from({length:16},(_,i)=>`<rect x="${234+i%4*16}" y="${53+Math.floor(i/4)*18}" width="13" height="15" rx="2" fill="${[1,2,4,7,9,10].includes(i)?'#7fa7a0':'#e2e9db'}"/>`).join('')}<g class="paint-sway"><path d="M48 119l38-72 10 6-35 75z" fill="#d7a066" stroke="#916c4f" stroke-width="2"/><path d="M48 119l-2 24 15-15z" fill="#a6c7ac"/></g><path class="scan-streak" d="M220 51h88" stroke="#d89964" stroke-width="3"/>`;
 if(ch===4)decor=`<path d="M34 171V61h58v50h64v58h73V88h65" fill="none" stroke="#a2bd8d" stroke-width="25" stroke-linejoin="round"/><path class="flight-line" d="M34 171V61h58v50h64v58h73V88h65" fill="none" stroke="#f7f9e6" stroke-width="3" stroke-dasharray="5 7"/><path class="gem-bob" d="M293 60l18 18-18 27-18-27z" fill="#eece72" stroke="#b09853" stroke-width="2"/>`;
 if(ch===5)decor=`<path d="M11 174q68-25 134 0t129 0t77 0v32H0z" fill="#a6ccbd"/><g class="boat-rock"><path d="M225 142h98l-21 25h-59z" fill="#dd9f73" stroke="#986649" stroke-width="2"/><path d="M272 74v69m3-64 37 56h-37z" fill="#fff9dc" stroke="#987456" stroke-width="2"/></g><g class="star-orbit"><path d="M61 52l5 10 12 2-9 8 2 12-10-6-11 6 2-12-8-8 12-2z" fill="#e9c778"/></g>`;
 return `<svg class="story-art ${compact?'compact':''}" viewBox="0 0 350 210" role="img" aria-label="${WORLDS[ch][0]}，机器人小芽的冒险插画"><rect width="350" height="210" rx="20" fill="${accent}"/><circle cx="297" cy="36" r="20" fill="#fffaf088"/><path class="cloud-drift" d="M22 46q0-15 15-13 8-20 24-7 16-1 19 17z" fill="#fffdf480"/>${decor}<g transform="translate(115 66) scale(.88)">${botArt(mood)}</g>${mood==='confused'?'<text class="question-bob" x="211" y="64" font-size="30" fill="#9b794d" font-weight="bold">?</text>':'<g class="twinkle" fill="#fffef5"><path d="M212 57l3 8 8 3-8 3-3 8-3-8-8-3 8-3z"/></g>'}</svg>`}
function speech(text,mood='think'){return `<div class="coach-speech"><svg viewBox="0 0 130 145" aria-hidden="true">${botArt(mood)}</svg><p><b>小芽</b>${text}</p></div>`}
const STORIES={
 rules:['水果邮局第一天开门，我还分不清两种水果。','你来教我一条规则，把水果送进正确篮子。'],
 knn:['新水果没有标签，我能向老邻居求助吗？','帮我选对线索，再看邻居怎样投票。'],
 reg:['我想把星星送到目标上，可总是偏了一点。','你调整预测线，我来看看离目标还差多少。'],
 tree:['花园门口需要一个会问问题的小守卫。','用两个问题，让不同的小点走进正确的门。'],
 nn:['有些规律弯弯绕绕，一条直线可不够。','搭一个小大脑，看它怎样一点点学会。'],
 conv:['你看到的是图案，我看到的是一格格数字。','给我一片小滤镜，我们一起找出边缘。'],
 vision:['我还没见过你画的形状，没办法猜对。','先给我两类例子，再画一张新图考考我。'],
 rl:['钻石在迷宫另一边，可我还不知道怎么走。','告诉我什么值得做，再让我去探索。'],
 agent:['模拟桌面上有一个文件，我还不会整理。','让我通过试错，学会打开、整理和保存。'],
 go:['小棋盘上，每个落点都会改变局面。','先教我给提子机会打分，再跟我下一会儿。']};
function storyCopy(){let s=Engine.s;if(s.v==='dirty')return ['哎呀！包裹上的标签出现了错误。','点出贴错标签的水果，帮我重新认清它们。'];if(s.v==='balance')return ['我只见过苹果，居然把所有东西都猜成苹果！','给我看看橘子，才有机会学会两类。'];if(s.v==='vote')return ['我只听一个邻居的意见，被一个错误标签骗了。','试试多问几个邻居，再让大家投票。'];if(s.v==='overfit')return ['旧题我全会，新题却总错。这算学会了吗？','帮我从“背题”切换到“学规律”。'];if(s.v==='obstacle')return ['我熟悉的道路突然被挡住了。','换条路重新探索，把钻石带回来。'];return STORIES[s.type]}
function tasks(){let s=Engine.s,op=k=>guide.ops.has(k),items=[],add=(title,tip,keys,actions,done)=>items.push({title,tip,keys,actions,done});
 if(s.type==='rules')add('调好分拣规则','拖动下面的滑条，看看传送带上的水果会被送进哪只篮子。',['threshold'],[],()=>op('threshold'));
 if(s.type==='knn'){
 if(s.v==='features')add('选一种真正有用的信息','点“重量 + 甜度”，看看机器人是否分得更准。',['feature'],[],()=>s.feature);
 else if(s.v==='dirty')add('核对原始记录，修正错误标签','点击上方档案核对原始记录，再纠正标签；也可以点图中的样本切换标签。',[],[],()=>op('canvas'));
 else if(s.v==='balance')add('给小芽看看橘子','点击补充样本。看看橘子类的识别结果是否改变。',[],['balance'],()=>s.train.some(p=>p.c===1));
 else if(['draw','lab'].includes(s.v))add('亲手添加两颗水果','先选择类别，再点空白处添加样本。观察它如何影响附近的预测。',['label'],[],()=>s.added>=2);
 else if(s.v==='vote')add('让更多邻居一起投票','点 3 个邻居，注意虚线连接和预测颜色的变化。',['k'],[],()=>op('k'));
 else add('点一块空白，放入神秘水果','蓝色十字就是新水果；虚线告诉你它在参考谁。',[],[],()=>op('canvas'));
 }
 if(s.type==='reg'){
 if(s.v==='overfit')add('从背答案，换成学一条直线','点“学规律”，再看看新数据上的误差。',['model'],[],()=>s.model==='line');
 if(s.v==='manual'){add('先调整直线的倾斜程度','拖动斜率，再点“用当前模型试射”。让预测落点向金色目标靠近。',['w'],[],()=>op('w'));add('再把直线移到星星中间','拖动截距，继续缩小预测偏差。展开数据图，还能检查整条直线是否接近样本。',['b'],[],()=>op('b'))}
 else{if(s.v==='rate')add('把步子调小一点','学习率就是每次改动的幅度。先试 0.2，再训练。',['lr'],[],()=>op('lr'));add('让小芽自己调整预测线','点击训练。线会随着真实参数更新，逐渐靠近星星。',[],['train'],()=>s.trained>0)}
 }
 if(s.type==='tree'){add('设置第一扇门的位置','拖动 x 的分界线，让右半边的小点进入下一扇门。',['tx'],[],()=>op('tx'));add('设置第二扇门的位置','拖动 y 的分界线，让右上方的小点分到橙色区域。',['ty'],[],()=>op('ty'))}
 if(s.type==='nn'){if(s.kind!=='linear')add('为网络增加隐藏层','点“8 个节点”。单个神经元无法表示这类非线性边界。',['hidden'],[],()=>op('hidden')&&s.hidden>0);if(s.v==='rate')add('设置训练的步幅','先试 0.08。训练中观察损失是否逐渐降低。',['lr'],[],()=>op('lr'));add('开始训练，观察分类区域的变化','背景色是模型的判断区域。观察分类区域是否逐渐与样本类别相符。',[],['train'],()=>s.trained>0)}
 if(s.type==='conv'){add('选择要检测的边缘方向',s.v==='vertical'?'寻找左右亮度变化，请点“竖直边缘”。':'寻找上下亮度变化，请点“水平边缘”。',['filter'],[],()=>op('filter'));add('让滤镜扫过图片','在左图上拖动扫描框，检查每个位置的响应；也可以点击“开始扫描”自动演示。',[],['scan'],()=>s.scanned)}
 if(s.type==='vision'){
 add('先画竖线，保存为 A 类样本','在像素格里按住拖动，画一条竖线；也可以填入示例，然后保存。',[],['vertical','clear','sample'],()=>s.samples.some(p=>p.c===0));
 add('再画横线，保存为 B 类样本','当前类别已切到 B。先清空再画，或点“填入横线示例”。',[],['horizontal','clear','sample'],()=>s.samples.some(p=>p.c===1));
 if(['augment','boss','final'].includes(s.v))add('通过平移，增加不同位置的样本','打开平移增强，小芽会参考不同位置的线条。',[],['augment'],()=>s.aug);
 add('用这些例子训练识别器','点击训练，A 和 B 的样本就会进入模型。',[],['train'],()=>s.trained>0);
 if(!['augment','boss'].includes(s.v))add('重新画一张，再考考小芽','不要直接用原图。清空重画，或点一个格子改变线条，再点识别。',[],['clear','predict'],()=>s.predicted);
 if(s.v==='final')add('给你的第一个 AI 作品起个名字','保存后它会出现在 AI Lab，之后还能继续改进。',[],['save'],()=>s.saved);
 }
 if(s.type==='rl'){if(s.v==='obstacle')add('先把熟悉的路挡住','点“改变道路”，看看原来的路线还能不能走通。',[],['obstacle'],()=>s.changed);if(s.v==='reward')add('告诉小芽：找到钻石是好事','把终点奖励拖到正数，先试 +10。',['reward'],[],()=>s.reward>0);if(s.v==='explore')add('允许小芽试试陌生的方向','把探索率设为 0.3，表示约三成动作会随机尝试。',['eps'],[],()=>s.eps>0);add('让小芽练习走迷宫','点训练。它会真实尝试 150 回合，并更新每个方向的价值。',[],['train'],()=>s.trained>0);add('看它自己走一次','点播放策略。小芽会按照学到的方向，逐格走向钻石。',[],['route'],()=>op('route'))}
 if(s.type==='agent'){add('让小芽学习整理文件','点击训练，它会在模拟桌面试错 200 次。',[],['train'],()=>s.trained>0);add('看小芽独立完成任务','播放时会依次展示它打开、整理和保存的选择。',[],['route'],()=>op('route'))}
 if(s.type==='go'){add('先训练一个落子评分器','它只学习一步提子机会，不代表已经学会整盘围棋。',[],['train'],()=>s.trained>0);add('你执黑，点一个空位落子','白棋会按照训练后的评分回应。下完可以继续玩。',[],[],()=>s.turns>0)}
 return items;
}
function currentTask(){let list=tasks(),i=list.findIndex(t=>!t.done());guide.step=i<0?list.length:i;return list[i]||null}
function guideButton(a){let s=Engine.s,labels={train:s.type==='nn'?'开始训练 · 200 轮':s.type==='rl'?'开始练习 · 150 回合':s.type==='agent'?'学习整理文件':s.type==='go'?'训练提子评分器':'开始训练',sample:'保存到 '+(s.label?'B · 横线':'A · 竖线'),vertical:'填入竖线示例',horizontal:'填入横线示例',clear:'清空重画',augment:s.aug?'✓ 增强已开启':'开启平移增强',predict:'让小芽认一认',scan:'开始扫描',route:'▶ 看小芽自己做',balance:'＋ 补充橘子样本',obstacle:'改变道路',save:'保存我的作品',resetboard:'重开棋局'};return `<button class="${['clear','vertical','horizontal'].includes(a)?'secondary':'primary'} ${guideBusy?'working':''}" ${guideBusy?'disabled':''} onclick="${a==='save'?'saveProject()':`act('${a}')`}">${guideBusy&&a==='train'?'小芽正在练习…':labels[a]||a}</button>`}
function guideField(k){let s=Engine.s,buttons=(options)=>`<div class="choice-chips" role="group">${options.map(([val,label])=>`<button class="${String(+s[k])===String(val)||String(s[k])===String(val)?'picked':''}" onclick="setParam('${k}','${val}')">${label}</button>`).join('')}</div>`;
 if(k==='k')return buttons([[1,'1 个邻居'],[3,'3 个邻居'],[5,'5 个邻居'],[9,'9 个邻居']]);
 if(k==='hidden')return buttons([[0,'1 个神经元'],[4,'4 个节点'],[8,'8 个节点'],[12,'12 个节点']]);
 if(k==='filter')return `<div class="filter-choices">${[['blur','模糊','▦'],['vertical','竖直边缘','▥'],['horizontal','水平边缘','▤']].map(([v,t,icon])=>`<button class="${s.filter===v?'picked':''}" onclick="setParam('filter','${v}')"><strong>${icon}</strong>${t}</button>`).join('')}</div>`;
 if(k==='feature')return buttons([[0,'🎲 随机编号'],[1,'⚖ 重量 + 甜度']]);
 if(k==='model')return buttons([['memory','📒 只背答案'],['line','📈 学习规律']]);
 if(k==='label')return buttons([[0,'🍏 A 类'],[1,'🍊 B 类']]);
 let config={threshold:['水果分界线',0,1,.01],w:['倾斜程度（斜率）',-1,2,.01],b:['上下位置（截距）',-.5,1,.01],lr:['训练步幅（学习率）',.001,s.type==='nn'?.3:2,.001],tx:['左右分界线 x',0,1,.01],ty:['上下分界线 y',0,1,.01],reward:['找到钻石的奖励',-2,15,1],eps:['尝试新方向的比例',0,1,.05]}[k];return `<label class="guided-slider"><span>${config[0]}</span><b id="val-${k}">${Number(s[k]).toFixed(2)}</b><input aria-label="${config[0]}" type="range" min="${config[1]}" max="${config[2]}" step="${config[3]}" value="${s[k]}" oninput="previewParam('${k}',this.value)" onchange="setParam('${k}',this.value)"><span class="range-ends"><small>${config[1]}</small><small>${config[2]}</small></span></label>`}
function guidedControls(){let t=currentTask(),s=Engine.s;if(s.type==='vision'&&t){if(guide.step===0)s.label=0;else if(guide.step===1)s.label=1}
 return `<div class="action-instruction"><span class="step-dot">${t?guide.step+1:'✓'}</span><div><small>${t?'现在只做这一步':'准备好了'}</small><h3>${t?t.title:'操作完成，可以开始测试了'}</h3><p>${t?t.tip:'如果还想改进，可以展开更多调整；准备好后点击下面的挑战按钮。'}</p></div></div>${t?`<div class="spotlight-control">${t.keys.map(guideField).join('')}<div class="guided-actions">${t.actions.map(guideButton).join('')}</div>${!t.keys.length&&!t.actions.length?'<span class="touch-cue">☝ 点上面的画面试试看</span>':''}</div>`:''}<details class="extra-controls" ${!t||s.last&&!s.last.pass?'open':''}><summary>${!t?'继续调整模型 / 重新训练':'全部实验设置'}</summary>${Engine.controls()}</details>`}
function sceneLegend(){let s=Engine.s;return {rules:'🍏 绿色：苹果　🍊 橙色：橘子　虚线：你的判断规则',knn:'🍏 / 🍊：已知样本　✛：新水果　虚线：参考的邻居',reg:'★ 星星：真实目标　绿线：小芽的预测',tree:'小点：样本　背景色：模型分到的区域',nn:'圆点：真实类别　背景色：当前预测区域',vision:'按住拖动画图；从已填色的格子开始拖动，可以连续擦除。',conv:'左边：原始像素　右边：滤镜扫描后的结果',rl:'🤖 起点　◆ 钻石　深色：墙　小芽会逐格移动',agent:'这是封闭的模拟桌面；播放后观察操作顺序。',go:'黑棋是你，白棋是模型。点击棋盘空位落子。'}[s.type]}
function observation(){let s=Engine.s,m=Engine.metric();if(m){let verdict=m.format==='mse'?`预测和目标的平均平方偏差是 ${m.value.toFixed(3)}。`:`在新样本上，它目前的识别准确率是 ${Math.round(m.value*100)}%。`;return verdict+(m.format==='pct'&&m.value>=.8?' 这次表现不错，接下来看看它依据什么判断。':' 接下来由你帮助它改善。')}
 return {vision:'没有参考样本，小芽还没有办法识别图像。先收集两类例子。',conv:'原图还没有经过滤镜；右边暂时没有特征图。',rl:'还没训练，小芽一直重复同一个动作，走不出起点。',agent:'还没学过操作顺序，光会打开文件无法完成任务。',go:'评分器还没训练。先学习怎样给一步提子机会打分。'}[s.type]}
function sampleTrail(){let s=Engine.s;if(!s.test)return '';let samples=s.test.slice(0,8);return `<div class="sample-trail">${samples.map((p,i)=>{let pred=Engine.predict(p),ok=s.type==='reg'?Math.abs(pred-p.y)<.12:pred===p.c;return `<span class="sample-ticket ${ok?'hit':'miss'}" style="--i:${i}" title="${s.type==='reg'?'预测偏差 '+Math.abs(pred-p.y).toFixed(2):'实际 '+(p.c?'B':'A')+'，预测 '+(pred?'B':'A')}">${s.type==='reg'?'★':p.c?'🍊':'🍏'}<b>${ok?'✓':'×'}</b></span>`}).join('')}</div><small class="trail-label">前 8 个新样本的真实预测结果 · ✓ 正确 / × 需改进</small>`}
function lessonHeader(){return `<div class="lessonhead"><button class="back" aria-label="返回地图" onclick="navigate('${labMode?'lab':'home'}')">←</button><div><div class="eyebrow" style="margin:0">${labMode?'AI LAB':WORLDS[current.chapter][0]+' · 第 '+current.id+' 关'}</div><h2>${esc(current.title)}</h2></div><button class="motion-toggle" aria-label="切换动画" onclick="toggleMotion()">${motionOn?'◉ 动画':'◎ 静态'}</button></div>`}
const baseRenderLesson=renderLesson;
renderLesson=function(){if(labMode){baseRenderLesson();return}stopAnimation();let l=current,copy=storyCopy();let content=lessonHeader()+`<div class="journey-steps">${['接下任务','看小芽尝试','动手教它','挑战过关'].map((t,i)=>`<span class="${phase===i?'current':phase>i?'done':''}"><b>${phase>i?'✓':i+1}</b>${t}</span>`).join('')}</div>`;
 if(phase===0){content+=`<section class="story-intro"><div class="story-picture">${sceneArt(l.chapter,'confused')}<span class="scene-caption">${WORLDS[l.chapter][0]}</span></div><div class="story-dialogue"><span class="character-label">小芽发来求助</span><h3>${copy[0]}</h3><p>${copy[1]}</p></div></section><section class="decision-box"><h3><span>轮到你啦</span> ${l.question}</h3><div class="choices">${l.options.map((o,i)=>`<button class="choice ${decision===i?'selected':''}" onclick="choose(${i})"><span class="choice-letter">${String.fromCharCode(65+i)}</span>${o}<b>${decision===i?'✓':'→'}</b></button>`).join('')}</div><div class="decision-response" aria-live="polite">${decision!==null?(decision===l.answer?'小芽：我记住你的想法了，来试一次！':'小芽：让我试试看，结果会给我们线索。'):'先选出你的判断，再用实验检验。'}</div></section><div class="lessonbottom"><button class="primary wide" ${decision===null?'disabled':''} onclick="nextPhase()">一起看小芽试一次 →</button></div>`;
 }else{
 content+=phase===1?speech(observation(),'confused'): `<div id="guide-mini" class="guide-mini">${guideMiniHTML()}</div>`;
 content+=`<div class="playlayout guided-layout"><section class="world ${phase===1?'observe-world':''}">${Engine.html().replace('<div class="controls"',`<div class="scene-legend">${sceneLegend()}</div><div class="controls"`)}</section><aside class="brain"><h3>✳ 小芽的大脑</h3><div id="brain-visual"></div><code id="brain-content"></code><button class="secondary wide" onclick="showBrain()">放大看看</button></aside></div>${phase===1?`<section class="observation-result">${sampleTrail()}<div class="discovery-caption"><span>💡</span><p>${l.engine==='knn'&&l.variant==='vote'?'一个邻居可能出错。多问几位，会发生什么？':l.engine==='reg'?'目标和预测之间的距离，就是我们要减少的误差。':l.engine==='nn'?'看看哪些样本落在了错误的分类区域；训练会根据这些错误调整权重。':'先看到结果，再尝试改变一个因素。'}</p></div></section><div class="lessonbottom"><button class="primary wide" onclick="discover()">我来帮它！下一步怎么做？ →</button></div>`:`<div class="lesson-tools"><button onclick="showBrain()">✳ 看大脑</button><button onclick="showWhy()">为什么？</button><button onclick="showCode()">看代码</button><button onclick="showTaskHelp()">☝ 操作提示</button></div><div id="challenge-footer" class="lessonbottom"></div>`}`;
 }
 if(phase===0&&typeof BRIEF_LEVELS!=='undefined'&&BRIEF_LEVELS.has(l.id)){const start=content.indexOf('<section class="decision-box">');content=content.slice(0,start)+`<section class="mission-brief"><span>${PLAY_MODES[l.id-1]}</span><h3>这次，由你来动手。</h3><p>${l.desc}</p><small>带着这个问题去试：${l.question}</small></section><div class="lessonbottom"><button class="primary wide" onclick="acceptMission()">接下任务，进入实验 →</button></div>`}shell(content,'home');document.body.classList.toggle('still',!motionOn);
 if(phase>0){if(phase===1){$('#controls').innerHTML='<div class="observe-hint">👀 现在只观察。点下方“我来帮它”，就会出现你要操作的按钮。</div>';Engine.s.observing=true}else{Engine.s.observing=false;$('#controls').innerHTML=guidedControls()}Engine.draw();let c=$('#canvas');if(c)c.addEventListener('pointerdown',e=>{if(phase===1||guideBusy)return;let b=c.getBoundingClientRect();Engine.click((e.clientX-b.left)*520/b.width,(e.clientY-b.top)*320/b.height);guide.ops.add('canvas');refreshGuide()});let bar=$('.worldbar');if(bar)bar.innerHTML=`<span>小芽的实验现场</span><span>${phase===1?'先看它做':'试试你的想法'}</span>`;refreshChallenge();}
};
function plainGoal(l){let s=Engine.s;if(s.type==='reg')return '让预测线靠近目标，再通过新数据测试。';if(s.type==='vision')return ['boss','augment'].includes(s.v)?'让新位置的线条至少 80% 被认对。':'教会两类图案，重新画一张来测试。'+(s.v==='final'?'最后保存作品。':'');if(s.type==='conv')return '找对边缘方向，并完成一次滤镜扫描。';if(s.type==='rl')return '让小芽自己在 16 步内到达钻石。';if(s.type==='go')return '训练提子评分器，再和它交换一次落子。';if(s.type==='agent')return '让小芽自己完成打开 → 整理 → 保存。';return `让新样本准确率达到 ${s.type==='nn'||['vote','dirty','balance','tree'].includes(s.v)?85:80}%。`}
function refreshChallenge(){let el=$('#challenge-footer');if(!el)return;let t=currentTask(),n=tasks().length;el.innerHTML=`<span class="checklist-status">${guideBusy?'正在计算 / 播放；完成后继续':t?'已完成 '+guide.step+' / '+n+' 步':'✓ 操作完成'}</span>${guideBusy?'<button class="secondary" onclick="pauseExperiment()">停止，保留进度</button>':'<button class="secondary" onclick="resetExperiment()">重新开始本次实验</button>'}<button class="primary" ${t||guideBusy?'disabled':''} onclick="challenge()">${t?'先完成上面的操作':'用新样本测试 →'}</button>`}
function refreshGuide(force=false){if(labMode||phase<2)return;let previous=guide.step,t=currentTask();if(previous!==guide.step||force){$('#controls').innerHTML=guidedControls();if(previous!==guide.step){let note=$('#engine-note');if(note)note.textContent='✓ 这一步完成了！继续看下面的新任务。'}}refreshChallenge();let mini=$('#guide-mini');if(mini)mini.innerHTML=guideMiniHTML();let readout=$('#live-readout');if(readout)readout.innerHTML=readoutHTML()}
function readoutHTML(){let s=Engine.s,m=Engine.metric();if(!m)return '';let before=guide.before;return `<span>${s.type==='reg'?'离目标的误差':'新样本准确率'}</span><b>${m.format==='mse'?m.value.toFixed(3):Math.round(m.value*100)+'%'}</b>${before?`<small>开始时 ${before.format==='mse'?before.value.toFixed(3):Math.round(before.value*100)+'%'}</small>`:''}`}
const coreDraw=Engine.draw.bind(Engine);Engine.draw=function(){coreDraw();if(typeof document==='undefined')return;let s=this.s;if(!s||labMode)return;let canvas=$('#canvas');if(canvas){let c=canvas.getContext('2d'),px=x=>35+x*450,py=y=>275-y*260;
 if(['knn','rules'].includes(s.type)){c.textAlign='center';c.textBaseline='middle';c.font='18px sans-serif';for(let p of s.train)c.fillText(p.c?'🍊':'🍏',px(p.x),py(p.y));c.textAlign='start';c.textBaseline='alphabetic'}
 if(s.type==='rules'){c.beginPath();c.strokeStyle='#476e41';c.lineWidth=3;c.setLineDash([7,4]);c.moveTo(35,py(s.threshold));c.lineTo(485,py(s.threshold));c.stroke();c.setLineDash([]);c.fillStyle='#35593c';c.font='12px sans-serif';c.fillText('← 你的分界线',365,Math.max(29,py(s.threshold)-9))}
 if(s.type==='reg'){c.fillStyle='#d79a47';c.font='18px sans-serif';c.textAlign='center';for(let p of s.train)c.fillText('★',px(p.x),py(p.y)+5);c.textAlign='start'}
 if(s.type==='conv'&&s.scanIndex!==undefined){let i=s.scanIndex%36,x=i%6,y=Math.floor(i/6);c.strokeStyle='#de965f';c.lineWidth=3;c.strokeRect(20+x*24,44+y*24,70,70);c.strokeRect(298+x*29,53+y*29,27,27)}
 }
 let met=$('#metrics');if(met&&Engine.metric())met.innerHTML=`<div id="live-readout" class="live-readout" aria-live="polite">${readoutHTML()}</div>`;
 if(s.type==='rl'){let board=$('#board');if(board){let loc=s.path.length?s.path.at(-1):0;board.innerHTML=Array.from({length:25},(_,i)=>`<button aria-label="格子 ${i+1}" class="tile ${s.walls.includes(i)?'wall':''} ${s.path.includes(i)?'path':''} ${i===loc?'robot-here':''}" onclick="tile(${i})">${i===loc?'🤖':i===24?'◆':s.path.includes(i)?'·':''}</button>`).join('')}}
};
const coreOpenLevel=openLevel;openLevel=function(id){stopAnimation();current=LEVELS.find(l=>l.id===id);labMode=false;phase=0;decision=null;Engine.init(current);guide={step:0,ops:new Set(),before:Engine.metric(),seen:false};renderLesson();window.scrollTo(0,0)};
nextPhase=function(){phase=1;renderLesson();let s=Engine.s;if(s.type==='rl'){s.path=[0];let i=0;observeTimer=setInterval(()=>{if(++i>4){clearInterval(observeTimer);observeTimer=null;return}s.path.push(0);s.message='还没训练，它在起点重复尝试向上，撞到了边界。';Engine.draw()},380)}};
discover=function(){phase=2;renderLesson();showDiscovery()};
function showDiscovery(){let s=Engine.s,icons={knn:['🍏','↔','🍊'],rules:['🍏','⎯','🍊'],reg:['★','↔','╱'],tree:['？','↙ ↘','✓'],nn:['◉','→','✳'],vision:['▥','＋','▤'],conv:['▦','→','▧'],rl:['🤖','→','◆'],agent:['▤','→','✓'],go:['●','→','○']}[s.type];modal('这一关的关键原理',`<div class="discovery-visual">${icons.map((x,i)=>`<span class="discovery-object" style="--i:${i}">${x}</span>`).join('')}</div><p class="discovery-text">${current.why}</p><button class="primary wide" onclick="closeModal();focusTask()">懂了，带我做第一步 →</button>`)}
function focusTask(){let el=$('#controls');if(el&&typeof el.scrollIntoView==='function')el.scrollIntoView({behavior:reducedMotion()?'auto':'smooth',block:'nearest'})}
function showTaskHelp(){let t=currentTask();modal('这一步这样做',`${speech(t?t.tip:'点击“考考小芽”，看看它能不能通过新任务。')}<p>${sceneLegend()}</p><button class="primary wide" onclick="closeModal();focusTask()">带我到操作位置 ↓</button>`)}
setParam=function(k,v){let wasBusy=guideBusy;stopAnimation();Engine.set(k,v);guide.ops.add(k);let el=$('#val-'+k);if(el)el.textContent=Number(v).toFixed(2);refreshGuide(wasBusy||['k','hidden','filter','feature','model','label'].includes(k))};
const baseAct=act;
act=function(a){if(labMode){baseAct(a);return}stopAnimation();if(a==='train'&&['nn','reg','rl'].includes(Engine.s.type)){trainAnimated();return}if(a==='scan'){Engine.action(a);guide.ops.add(a);let s=Engine.s,i=0;guideBusy=true;observeTimer=setInterval(()=>{s.scanIndex=i++;Engine.draw();if(i>=36){clearInterval(observeTimer);observeTimer=null;guideBusy=false;refreshGuide(true)}},reducedMotion()?1:55);return}Engine.action(a);if(['obstacle','restoremap'].includes(a))guide.ops.delete('route');guide.ops.add(a);refreshGuide(true);Engine.draw();if(a==='route'){let s=Engine.s;if(s.type==='rl'){let path=[...s.path],msg=s.message,i=1;s.path=[path[0]];guideBusy=true;refreshChallenge();animationTimer=setInterval(()=>{s.path=path.slice(0,++i);s.message='小芽正在执行第 '+(i-1)+' 步…';if(i>=path.length){stopAnimation();s.message=msg;refreshGuide(true)}Engine.draw()},reducedMotion()?1:220)}if(s.type==='agent'){let route=[...s.route],msg=s.message,i=0;s.state=0;s.log=[];guideBusy=true;refreshChallenge();Engine.draw();animationTimer=setInterval(()=>{let a=route[i++];s.log.push(['打开文件','整理内容','保存文件','关闭窗口'][a]);s.state=a===s.state?s.state+1:0;if(i>=route.length){stopAnimation();s.message=msg;refreshGuide(true)}Engine.draw()},reducedMotion()?1:650)}}};
function trainAnimated(){let s=Engine.s,type=s.type,total=type==='nn'?200:type==='rl'?150:80,part=type==='nn'?20:type==='rl'?15:8,done=0;s.trainingError=false;guideBusy=true;$('#controls').innerHTML=guidedControls();refreshChallenge();observeTimer=setInterval(()=>{Engine.action('train',part);if(s.trainingError){stopAnimation();refreshGuide(true);Engine.draw();return}done+=part;s.message=`小芽正在练习：${done} / ${total} ${type==='nn'?'轮':type==='rl'?'回合':'次更新'}。画面来自当前模型的真实结果。`;Engine.draw();if(done>=total){clearInterval(observeTimer);observeTimer=null;guideBusy=false;guide.ops.add('train');s.message='练习完成！看看现在的预测和刚开始有什么不同。';refreshGuide(true);Engine.draw()}},reducedMotion()?1:110)}
const baseTile=tile;tile=function(i){if(!labMode&&(phase===1||guideBusy))return;baseTile(i);if(Engine.s.type==='rl')guide.ops.delete('route');guide.ops.add('tile');refreshGuide(true)};
resetExperiment=function(){stopAnimation();Engine.init(current);if(labMode&&current.engine==='knn')Engine.s.train=[];guide={step:0,ops:new Set(),before:Engine.metric(),seen:false};renderLesson()};
const baseCommitProject=commitProject;commitProject=function(){baseCommitProject();refreshGuide(true)};
function confetti(){return `<div class="confetti" aria-hidden="true">${Array.from({length:18},(_,i)=>`<i style="--x:${(i*37)%100}%;--d:${i%6*.12}s;--r:${i*31}deg;background:${['#a9ce80','#efb86d','#a3c6d5','#d5b5d2'][i%4]}"></i>`).join('')}</div>`}
challenge=function(){if(!labMode&&currentTask()){toast('先完成小芽提示的操作，再挑战。');focusTask();return}phase=3;renderLesson();let r=Engine.test();if(r.pass){progress[current.id]={date:new Date().toISOString(),result:r.detail};persist('academy-progress-v1',progress);let before=guide.before,after=Engine.metric();modal('任务完成 · 新能力 +1',`<div class="victory-art">${confetti()}${sceneArt(current.chapter,'happy')}</div><h2 class="resulttitle">击掌！我们做到了。</h2>${before&&after?`<div class="before-after"><div>刚开始<b>${before.format==='mse'?before.value.toFixed(3):Math.round(before.value*100)+'%'}</b></div><span>→</span><div>现在<b>${after.format==='mse'?after.value.toFixed(3):Math.round(after.value*100)+'%'}</b></div></div>`:''}<p>${esc(r.detail)}</p><div class="reward-discovery">✦ 带走一个发现：${current.why}</div><div class="victory-actions"><button class="primary wide" onclick="closeModal();travelNext()">${current.id<30?'和小芽去下一站 →':'前往自由实验室 →'}</button><button onclick="closeModal();saveProject()">保存这次作品</button></div>`)}else{modal('还差一点，一起修好它',`${speech('没关系，这次结果给了我们新线索。','confused')}<p>${esc(r.detail)}</p><div class="feedback">${hint()}</div><button class="primary wide" style="margin-top:16px" onclick="closeModal();backToTrain();focusTask()">根据提示继续调整 →</button>`)}};
function travelNext(){if(current.id>=30){navigate('lab');return}let id=current.id+1,next=LEVELS[id-1],newChapter=next.chapter!==current.chapter;modal(newChapter?'下一章 · '+WORLDS[next.chapter][0]:'冒险继续',`<div class="travel-comic"><div><span class="comic-label">刚刚</span>${typeof activityArt==='function'?activityArt(current):sceneArt(current.chapter,'happy',true)}<p>${esc(current.title)}<br><b>✓ 任务完成</b></p></div><div><span class="comic-label">下一站</span>${typeof activityArt==='function'?activityArt(next):sceneArt(next.chapter,'confused',true)}<p>${esc(next.title)}<br><b>${next.desc}</b></p></div></div>${speech(newChapter?WORLDS[next.chapter][1]:'带上刚学会的本领，我们去解决下一个问题！')}<button class="primary wide" onclick="closeModal();openLevel(${id})">出发！→</button><button class="wide" onclick="closeModal();navigate('home')">先回地图休息一下</button>`)}
function illustratedHome(){let next=LEVELS.find(l=>!progress[l.id])||LEVELS[29];shell(`<section class="adventure-hero"><div><div class="eyebrow">小芽的成长冒险 · SEASON 01</div><h1>带上好奇心，<br>教 AI 认识世界。</h1><p>30 个小任务。每次动手尝试，<br>都帮你理解 AI 的一种工作方式。</p><button class="primary" onclick="openLevel(${next.id})">${count()?'继续第 '+next.id+' 关':'和小芽一起出发'} →</button></div><div class="hero-cartoon">${sceneArt(chapter,'happy')}</div></section><div class="sectionhead"><h2>我们的冒险路线</h2><button class="motion-toggle" onclick="toggleMotion()">${motionOn?'◉ 动画开启':'◎ 动画关闭'}</button></div><div class="chapters">${CHAPTERS.map((c,i)=>`<button class="chapter ${chapter===i?'selected':''}" onclick="chooseChapter(${i})">${c[0]} ${WORLDS[i][0]}</button>`).join('')}</div><section class="chapter-banner"><span>${CHAPTERS[chapter][0]}</span><div><h3>${WORLDS[chapter][0]}</h3><p>${WORLDS[chapter][1]}</p></div><small>${LEVELS.filter(l=>l.chapter===chapter&&progress[l.id]).length}/5 完成</small></section><div class="quest-path">${LEVELS.filter(l=>l.chapter===chapter).map((l,i)=>`<button class="quest-stop ${progress[l.id]?'finished':''} ${l.id===next.id?'next-stop':''}" onclick="openLevel(${l.id})"><span class="quest-node">${progress[l.id]?'✓':String(l.id).padStart(2,'0')}</span><span class="quest-art">${typeof activityArt==='function'?activityArt(l):sceneArt(l.chapter,progress[l.id]?'happy':'confused',true)}</span><span class="quest-copy"><small>${l.title.includes('挑战')?'⚔ BOSS 挑战':i===0?'新发现':'动手实验'}</small><strong>${esc(l.title)}</strong><span>${l.desc}</span></span><span class="quest-arrow">${progress[l.id]?'重玩':'出发'} ↗</span></button>`).join('')}</div><div class="introstrip"><span style="font-size:28px">⚗</span><div><strong>想自己创造点什么？</strong><p class="muted">到 AI Lab 里，自由画数据、训练和测试。</p></div><button aria-label="打开AI Lab" onclick="navigate('lab')">↗</button></div>`);document.body.classList.toggle('still',!motionOn)}
home=illustratedHome;
home();

function previewParam(k,v){Engine.set(k,v);let el=$('#val-'+k);if(el)el.textContent=Number(v).toFixed(2)}

function guideMiniHTML(){let t=currentTask();return `<span>${t?'☝':'🎯'}</span><p><b>${t?'下一步：'+t.title:'操作完成，准备考考小芽'}</b>${plainGoal(current)}</p><button onclick="${t?'focusTask()':'challenge()'}">${t?'去操作 ↓':'挑战 →'}</button>`}

function pauseExperiment(){stopAnimation();Engine.s.message="已停止，保留已完成的参数更新。可以继续训练或调整设置。";refreshGuide(true);Engine.draw()}
